  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
  fields = { "details" },
})
classes.Conflict = errors.define({
  tag = "Conflict",
  categories = { "ConflictError" },
  matchers = { { status = 409 } },
  fields = { "details" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
  fields = { "details" },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
  fields = { "details" },
})
classes.SecurityCommandCenterLegacyDisabled = errors.define({
  tag = "SecurityCommandCenterLegacyDisabled",
  categories = { "BadRequestError" },
  matchers = {
    {
      status = 400,
      message = { includes = "Security Command Center Legacy has been permanently disabled" },
    },
  },
  fields = { "details" },
})
classes.ServiceDisabled = errors.define({
  tag = "ServiceDisabled",
  categories = { "AuthError" },
  matchers = { { status = 403, message = { includes = "has not been used in project" } } },
  fields = { "details" },
})

